window.AUTH=window.AUTH||{};window.AUTH["23-370"]={"d":"23-370","id":"2023/23-370","n":"Erlinger v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Paul Erlinger","date":"2024-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-370/294814/20240103160925322_Erlinger%20Merits%20Brief.pdf","side":"pet","n":80},{"k":"respondent","label":"Brief of respondent United States in support of petitioner","date":"2024-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-370/294850/20240103184303471_23-370tsUnitedStates.pdf","side":"res","n":63},{"k":"reply","label":"Reply of petitioner Paul Erlinger","date":"2024-03-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-370/302185/20240304152721783_Erlinger%20Merits%20Reply%20Brief.pdf","side":"pet","n":39}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r45_h31i.pdf","tr":true,"items":[{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"op":23,"sum":"The Court found that a defendant cannot be found guilty of a claim not included in the indictment.","sumSrc":"Oyez","by":{"0":"11, 12, 13, 37","1":"9, 13, 14, 21"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"op":69,"ar":35,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"0":"8, 13-16, 28, 30-31","1":"13, 15, 25","2":"2, 3"}},{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"op":127,"ar":21,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"0":"8, 11-13, 15-16, 20, 34-37, 41","1":"9, 12, 13, 14, 15, 21","2":"1, 3, 12, 17"}},{"t":"case","label":"Bhd. Ry. Carmen Div., Transp. Commc’ns Int’l Union, AFL-CIO v. Atchison, Topeka & Santa Fe Ry. Co.","cite":"956 F.2d 156","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/956/156/","by":{"0":"41"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Black v. State","cite":"287 N.E.2d 354","y":1972,"court":"Ind. Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/287/354/","op":2,"by":{"0":"40"}},{"t":"case","label":"Blakely v. Washington","cite":"542 U.S. 296","y":2004,"id":"2003/02-1632","sc":1,"op":20,"sum":"The Court held that an exceptional sentence increase based on the judge's determination that Blakely had acted with \"deliberate cruelty\" violated Blakely's Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"0":"12, 33, 41, 42","1":"14","2":"15, 16"}},{"t":"case","label":"Brooks v. Commonwealth","cite":"41 Va. 845","y":1843,"court":"Va. Gen. Ct.","url":"https://www.courtlistener.com/c/Va./41/845/","by":{"0":"35"}},{"t":"case","label":"Bruton v. United States","cite":"391 U.S. 123","y":1968,"id":"1967/705","sc":1,"sum":"The Supreme Court held that Bruton was substantially prejudiced against because of the high risk that the jury considered Evans’ confession when deciding Bruton’s guilt. Admitting Evans’ confession into evidence violated Bruton’s Sixth Amendment right to cross-examination. This decision expressly overruled Delli Paoli v. United States .","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Commonwealth v. Briggs","cite":"22 Mass. 429","y":1827,"url":"https://www.courtlistener.com/c/Mass./22/429/","sum":"Holding “government must prove every essential allegation,” including prior conviction, to the jury.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"596 U.S. 212","y":2022,"id":"2021/20-219","sc":1,"sum":"Emotional distress damages are not recoverable in a private action to enforce either the Rehabilitation Act of 1973 or the Affordable Care Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Cunningham v. California","cite":"549 U.S. 270","y":2007,"id":"2006/05-6551","sc":1,"op":3,"sum":"The Court ruled 6-3 that California's Determinate Sentencing Law was inconsistent with the Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"0":"12, 33","1":"14"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"op":23,"ar":9,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"0":"9, 16-18, 27, 38-39","1":"14-17, 19","2":"1, 4, 13, 20"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Graham v. West Virginia","cite":"224 U.S. 616","y":1912,"id":"scdb/1911-236","sc":1,"op":5,"ar":1,"sum":"The statute of West Virginia, providing that where a prisoner has been convicted and sentenced to the penitentiary, the question of Ms identity with one previously convicted one or more times can be tried on information, and if proved, imposing additional imprisonment in case of one prior conviction for five years, and in case of two convictions, for life, is not unconstitutional, as to one twice pre- viously …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28, 41","1":"13","2":"7, 9"}},{"t":"case","label":"Green Bay Fish Co. v. State","cite":"202 N.W. 667","y":1925,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W./202/667/","by":{"0":"35"}},{"t":"case","label":"Gryger v. Burke","cite":"334 U.S. 728","y":1948,"id":"scdb/1947-106","sc":1,"sum":"Petitioner was charged and convicted in a state court of Pennsylvania of being a fourth offender and sentenced to life imprisonment. In the proceeding on the fourth-offender charge, the only question of fact before the court was whether he was the same person who was convicted in four previous cases, and this he admitted and does not now deny.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Harris v. United States","cite":"536 U.S. 545","y":2002,"id":"2001/00-10666","sc":1,"op":1,"sum":"The Court held that section 924(c)(1)(A) defines a single offense, in which brandishing a firearm is a sentencing factor to be found by the judge, not an offense element to be found by the jury.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Hildwin v. Florida","cite":"490 U.S. 638","y":1989,"id":"1988/88-6066","sc":1,"op":1,"sum":"The Sixth Amendment does not require that the specific findings authorizing the imposition of the death sentence be made by a jury. Since the Court has held that the Amendment permits a judge to impose a death sentence when the jury recommends life imprisonment, Spaziano v. Florida,468 U. S. 447, it follows that the Amendment does not forbid the judge to make written findings authorizing the imposition of a death …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Hines v. State","cite":"26 Ga. 614","y":1859,"url":"https://www.courtlistener.com/c/Ga./26/614/","by":{"0":"35"}},{"t":"case","label":"Hurst v. Florida","cite":"577 U.S. 92","y":2016,"id":"2015/14-7505","sc":1,"op":1,"sum":"The Court held that Florida’s sentencing scheme violated the Sixth Amendment’s guarantee of a jury trial in light of the Supreme Court’s decision in Ring v. Arizona, which held that the Sixth Amendment required a jury to sentence the defendant to death.","sumSrc":"Oyez","by":{"0":"11, 13"}},{"t":"case","label":"Johnson v. State","cite":"55 N.Y. 512","y":1874,"url":"https://www.courtlistener.com/c/N.Y./55/512/","by":{"0":"35"}},{"t":"case","label":"Jones v. United States","cite":"526 U.S. 227","y":1999,"id":"1998/97-6203","sc":1,"op":7,"sum":"Authored by Justice David H. Souter, the Court ruled that the federal carjacking law established three separate offenses by the specification of elements, each of which must be charged by indictment, proved beyond a reasonable doubt, and submitted to a jury for its verdict.","sumSrc":"Oyez","by":{"0":"12, 16","1":"15"}},{"t":"case","label":"Kirkland v. United States","cite":"687 F.3d 878","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/687/878/","by":{"0":"6, 25"}},{"t":"case","label":"Long v. State","cite":"36 Tex. 6","y":1871,"url":"https://www.courtlistener.com/c/Tex./36/6/","by":{"0":"35"}},{"t":"case","label":"Mathis v. United States","cite":"579 U.S. 500","y":2016,"id":"2015/15-6092","sc":1,"op":16,"ar":10,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"0":"9, 17-18, 20, 27, 34, 38-40","1":"14, 16-19, 21, 23, 25","2":"1, 3-5, 9, 11, 13, 20"}},{"t":"case","label":"N.Y. State Rifle & Pistol Ass’n v. Bruen","cite":"597 U.S. 1","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/1/","sc":1,"by":{"0":"31","2":"7"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"sum":"The Court found that when an alien is convicted of conspiracy and held responsible for causing more than $10,000 in damages, the statute requirement used by the Immigration and Nationality Act (INA) to deport the alien is satisfied, even if the $10,000 is not established by a jury.","sumSrc":"Oyez","by":{"0":"27, 28"}},{"t":"case","label":"People v. Youngs","cite":"1 Cai. R. 37","y":1803,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Cai.%20R./1/37/","by":{"0":"34"}},{"t":"case","label":"Pereida v. Wilkinson","cite":"141 S. Ct. 754","y":2021,"id":"2020/19-438","sc":1,"op":2,"sum":"A nonpermanent resident seeking to cancel a lawful removal order fails to carry his burden of showing that he has not been convicted of a disqualifying offense when the statutory conviction on his record is ambiguous regarding whether a disqualifying offense formed the basis of his conviction.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 36","2":"1"}},{"t":"case","label":"Ring v. Arizona","cite":"536 U.S. 584","y":2002,"id":"2001/01-488","sc":1,"op":2,"sum":"The Court held that, because Arizona's enumerated aggravating factors operates as \"the functional equivalent of an element of a greater offense,\" the Sixth Amendment requires that they be found by a jury.","sumSrc":"Oyez","by":{"0":"12, 13"}},{"t":"case","label":"Rumsfeld v. F.A.I.R.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"op":2,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"S. Union Co. v. United States","cite":"567 U.S. 343","y":2012,"id":"2011/11-94","sc":1,"sum":"The Court held that the rule applied in Apprendi v. New Jersey, where the Sixth Amendment’s guarantee of a jury trial requires that any fact which increases the maximum punishment for a particular crime be proved to a jury, applies to the imposition of criminal fines.","sumSrc":"Oyez","by":{"0":"12","1":"14"}},{"t":"case","label":"Samia v. United States","cite":"599 U.S. 635","y":2023,"id":"2022/22-196","sc":1,"sum":"The admission of a nontestifying codefendant’s confession did not violate the Sixth Amendment’s Confrontation Clause where the confession as modified did not directly inculpate the defendant but used the descriptor “other person” and the jury was instructed to consider the confession only as to the codefendant.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36","2":"17"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"op":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"28, 36"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"op":24,"ar":1,"sum":"Observing that the “prejudice is likely to be especially strong in ACCA cases, where the relevant prior crimes are, by defnition, `violent' ”.","sumSrc":"opinion","by":{"0":"10, 25, 35, 38-39, 41","1":"14, 17, 18","2":"1, 16"}},{"t":"case","label":"Spaziano v. Florida","cite":"468 U.S. 447","y":1984,"id":"1983/83-5596","sc":1,"op":1,"sum":"At petitioner's trial for first-degree murder, the Florida trial court informed him that it would instruct the jury on lesser included, noncapital offenses, if he would waive the statute of limitations, which had expired as to those offenses. Petitioner refused to waive the statute, and the jury was instructed solely on capital murder. After the jury returned a verdict of guilty of first-degree murder, a sentencing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"State v. Compagno","cite":"51 So. 681","y":1910,"court":"La.","url":"https://www.courtlistener.com/c/So./51/681/","op":1,"by":{"0":"35"}},{"t":"case","label":"State v. Hudson","cite":"32 La. Ann. 1052","y":1880,"url":"https://www.courtlistener.com/c/La.%20Ann./32/1052/","op":7,"ar":2,"by":{"0":"35"}},{"t":"case","label":"State v. Lashus","cite":"11 A. 180","y":1887,"court":"Me.","url":"https://www.courtlistener.com/c/A./11/180/","by":{"0":"35"}},{"t":"case","label":"State v. Riley","cite":"110 A. 550","y":1920,"court":"Conn.","url":"https://www.courtlistener.com/c/A./110/550/","by":{"0":"35"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"op":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","2":"5"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"op":9,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"12","1":"14"}},{"t":"case","label":"United States v. Bordeaux","cite":"886 F.3d 189","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/886/189/","by":{"0":"19"}},{"t":"case","label":"United States v. Brown","cite":"67 F.4th 200","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/67/200/","op":1,"by":{"0":"10, 26, 29-30, 32-33, 37, 41","1":"24-26","2":"20"}},{"t":"case","label":"United States v. Burgin","cite":"388 F.3d 177","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/388/177/","op":1,"sum":"Describing the different occasions-inquiry as “intimately related” to “the exception in Apprendi for a prior conviction”.","sumSrc":"brief:1","by":{"0":"25","1":"23, 25"}},{"t":"case","label":"United States v. Cina","cite":"699 F.2d 853","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/699/853/","by":{"0":"40"}},{"t":"case","label":"United States v. Dantzler","cite":"771 F.3d 137","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/771/137/","by":{"0":"20"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"United States v. De La Torre","cite":"940 F.3d 938","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/940/938/","op":2,"by":{"0":"5","1":"4"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"op":7,"ar":4,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11","2":"6, 7, 8"}},{"t":"case","label":"United States v. Glispie","cite":"978 F.3d 502","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/978/502/","op":1,"by":{"0":"5","1":"4"}},{"t":"case","label":"United States v. Harris","cite":"447 F.3d 1300","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/447/1300/","op":1,"by":{"0":"25"}},{"t":"case","label":"United States v. Harris","cite":"794 F.3d 885","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/885/","op":1,"by":{"0":"25"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"United States v. Haymond","cite":"139 S. Ct. 2369","y":2019,"id":"2018/17-1672","sc":1,"op":10,"sum":"The Tenth Circuit’s judgment—that 18 U. S. C. §3583(k)’s last two sentences are unconstitutional and unenforceable—is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37","1":"14"}},{"t":"case","label":"United States v. Hennessee","cite":"932 F.3d 437","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/932/437/","by":{"0":"16, 20, 25, 37"}},{"t":"case","label":"United States v. Longoria","cite":"874 F.3d 1278","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/1278/","by":{"0":"37"}},{"t":"case","label":"United States v. O’Brien","cite":"560 U.S. 218","y":2010,"id":"2009/08-1569","sc":1,"sum":"The Court held that the fact that a firearm was a machine gun is an element to be proved to the jury beyond a reasonable doubt, not a sentencing factor to be proved to the judge at sentencing.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"United States v. Perry","cite":"908 F.3d 1126","y":2018,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/908/1126/","by":{"0":"25"}},{"t":"case","label":"United States v. Rodriquez","cite":"553 U.S. 377","y":2008,"id":"2007/06-1646","sc":1,"sum":"The Court held 6-3 that although the elements of a particular crime may not be considered \"serious,\" a defendant's prior record will have a considerable bearing on making the determination. A crime's seriousness may be greatly enhanced when its maximum sentence is increased due to the defendant's prior convictions for similar or related crimes.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"United States v. Santiago","cite":"268 F.3d 151","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/268/151/","op":1,"by":{"0":"25","1":"23, 25, 26"}},{"t":"case","label":"United States v. Thompson","cite":"421 F.3d 278","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/421/278/","sum":"Concluding that “[t]he data necessary to determine the ‘separateness’ of the occasions is inherent in the fact of the prior convictions”.","sumSrc":"brief:1","by":{"0":"20, 25","1":"23, 25"}},{"t":"case","label":"United States v. Weeks","cite":"711 F.3d 1255","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/711/1255/","op":1,"by":{"0":"25"}},{"t":"case","label":"Walton v. Arizona","cite":"497 U.S. 639","y":1990,"id":"1989/88-7351","sc":1,"op":1,"sum":"The Court held that the Arizona method of death penalty sentencing is not arbitrary and does not place an undue burden on the defendant.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Weaver v. State","cite":"583 N.E.2d 136","y":1991,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E.2d/583/136/","by":{"0":"40"}},{"t":"case","label":"Welch v. United States","cite":"578 U.S. 120","y":2016,"id":"2015/15-6418","sc":1,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"op":16,"ar":20,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2-4, 8, 11, 19-21, 23, 30","1":"7, 8, 10, 11, 20-23, 28","2":"14"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"1"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"1","1":"2, 6, 7, 9, 11, 12, 15, 18, 20, 21, 26"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)","(e)(1)","(e)(2)(B)","(a)(8)","(e)","(e)(2)(B)(ii)","(a)(2)(2012)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"2, 2, 6, 11, 16, 18, 23, 16, 2","1":"3, 3, 9, 10, 12, 16, 17, 4, 3, 3","2":"2"}},{"t":"usc","label":"18 U.S.C. § 3575","url":"https://www.law.cornell.edu/uscode/text/18/3575","subs":["(a)(1)"],"by":{"0":"24"}},{"t":"usc","label":"21 U.S.C. § 849","url":"https://www.law.cornell.edu/uscode/text/21/849","subs":["(e)(1)"],"by":{"0":"24"}},{"t":"usc","label":"21 U.S.C. § 860","url":"https://www.law.cornell.edu/uscode/text/21/860","subs":["(a)"],"by":{"0":"33"}},{"t":"law","label":"Pub. L. No. 91-452","url":"https://www.govinfo.gov/link/statute/84/922","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 91-513","url":"https://www.govinfo.gov/link/statute/84/1236","by":{"0":"24"}},{"t":"rule","label":"Fed. R. Civ. P. 42","url":"https://www.law.cornell.edu/rules/frcp/rule_42","subs":["(b)"],"by":{"0":"41"}},{"t":"case","label":"Carachuri-Rosendo v. Holder","cite":"560 U.S. 563","y":2010,"id":"2009/09-60","sc":1,"sum":"The Court held that a minor drug offense is not automatic grounds for deportation of a legal immigrant.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Maslenjak v. United States","cite":"582 U.S. 335","y":2017,"id":"2016/16-309","sc":1,"sum":"The Court determined that, for a naturalized American citizen to be stripped of her citizenship, the government has to prove that she obtained her citizenship illegally; if the underlying illegality is a false statement to government officials, the government must prove that the false statement influenced the citizenship process.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"McFadden v. United States","cite":"576 U.S. 186","y":2015,"id":"2014/14-378","sc":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"op":2,"ar":3,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Old Chief v. United States","cite":"519 U.S. 172","y":1997,"id":"1996/95-6556","sc":1,"op":5,"ar":5,"sum":"The Court ruled that a district court abuses its discretion under the Federal Rules of Evidence if it spurns a defendant's offer to concede a prior judgment and admits the full judgment record over the defendant's objection, when the name or nature of the prior offense raises the risk of a verdict tainted by improper considerations, and when the purpose of the evidence is solely to prove the element of prior conviction.","sumSrc":"Oyez","by":{"1":"26","2":"17"}},{"t":"case","label":"Oregon v. Kennedy","cite":"456 U.S. 667","y":1982,"id":"1981/80-1991","sc":1,"sum":"During respondent's trial for theft in an Oregon state court, the State's expert witness testified as to the value and identity of the property involved. On cross-examination, he acknowledged that he had once filed an unrelated criminal complaint against respondent, but explained that no action had been taken on his complaint. On redirect examination, the court sustained a series of objections to the prosecutor's …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"op":1,"sum":"In a prosecution under 18 U. S. C. §922(g) and §924(a)(2), the Government must prove both that the defendant knew he possessed a firearm and that he knew he belonged to the relevant category of persons barred from possessing a firearm.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26"}},{"t":"case","label":"Richardson v. Marsh","cite":"481 U.S. 200","y":1987,"id":"1986/85-1433","sc":1,"sum":"The Court held that not only did the jury receive instructions not to consider the confession in assessing Marsh’s guilt, but also the confession was redacted so that there was no incriminating evidence regarding Marsh’s actions. Without the implication that the evidence in the confession was incriminating, Marsh’s Confrontation Clause rights were not violated.","sumSrc":"Oyez","by":{"1":"27","2":"16"}},{"t":"case","label":"Ruan v. United States","cite":"597 U.S. 450","y":2022,"id":"2021/20-1410","sc":1,"sum":"For the crime of prescribing controlled substances outside the usual course of professional practice in violation of 21 U. S. C. §841, the mens rea “knowingly or intentionally” applies to the statute’s “except as authorized” clause.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"United States v. Barrera","cite":"2022 WL 1239052","y":2022,"court":"9th Cir. Apr. 27","by":{"1":"24"}},{"t":"case","label":"United States v. Belcher","cite":"40 F.4th 430","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/40/430/","by":{"1":"24"}},{"t":"case","label":"United States v. Blair","cite":"734 F.3d 218","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/734/218/","op":1,"by":{"1":"23"}},{"t":"case","label":"United States v. Elliott","cite":"703 F.3d 378","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/703/378/","op":3,"by":{"1":"23, 24"}},{"t":"case","label":"United States v. Evans","cite":"738 F.3d 935","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/935/","by":{"1":"23"}},{"t":"case","label":"United States v. Golden","cite":"2023 WL 2446899","y":2023,"court":"3d Cir. Mar. 10","sum":"Holding that “any error in failing to submit the Wooden issue to a jury * * * was harmless because the record makes clear beyond a reasonable doubt that a rational jury would have concluded that Golden’s offenses were committed on different ‘occasions’ ”.","sumSrc":"brief:1","by":{"1":"28"}},{"t":"case","label":"United States v. Hines","cite":"2023 WL 4053013","y":2023,"court":"E.D. Tenn. June 16","sum":"Stating that it “will hold a bifurcated trial at which the jury, if necessary, will decide whether [the defendant] committed his prior offenses on occasions different from one another”.","sumSrc":"brief:1","by":{"1":"27"}},{"t":"case","label":"United States v. Ivery","cite":"427 F.3d 69","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/427/69/","op":1,"by":{"1":"23"}},{"t":"case","label":"United States v. McCall","cite":"2023 WL 2128304","y":2023,"court":"11th Cir. Feb. 21","by":{"1":"24"}},{"t":"case","label":"United States v. Michel","cite":"446 F.3d 1122","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/446/1122/","by":{"1":"24"}},{"t":"case","label":"United States v. Perry","cite":"862 F.3d 620","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/862/620/","by":{"1":"5"}},{"t":"case","label":"United States v. Reed","cite":"39 F.4th 1285","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/39/1285/","by":{"1":"24"}},{"t":"case","label":"United States v. Robinson","cite":"43 F.4th 892","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/43/892/","by":{"1":"24"}},{"t":"case","label":"United States v. Rodriguez","cite":"2022 WL 17883607","y":2022,"court":"7th Cir. Dec. 23","sum":"Holding that “the record would necessarily convince a reasonable jury that Rodriguez had committed his prior offenses on different occasions,” rendering any alleged error harmless.","sumSrc":"brief:1","by":{"1":"28"}},{"t":"case","label":"United States v. Spears","cite":"443 F.3d 1358","y":2006,"url":"https://www.courtlistener.com/c/F.3d/443/1358/","by":{"1":"24"}},{"t":"case","label":"United States v. Stowell","cite":"82 F.4th 607","y":2023,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/82/607/","op":1,"by":{"1":"24, 28"}},{"t":"case","label":"United States v. Thomas","cite":"572 F.3d 945","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/572/945/","op":1,"by":{"1":"24"}},{"t":"case","label":"United States v. Valencia","cite":"66 F.4th 1032","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/66/1032/","by":{"1":"24"}},{"t":"case","label":"United States v. Walker","cite":"953 F.3d 577","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/953/577/","op":1,"by":{"1":"24"}},{"t":"case","label":"United States v. White","cite":"465 F.3d 250","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/250/","by":{"1":"23"}},{"t":"case","label":"Washington v. Recuenco","cite":"548 U.S. 212","y":2006,"id":"2005/05-83","sc":1,"op":1,"sum":"In a 7-to-2 decision authored by Justice Clarence Thomas, the Supreme Court held that Blakely violations do not \"necessarily render[] a criminal trial unfair or an unreliable vehicle for determining guilt or innocence.\" (quoting Neder v. United States , 527 U.S. 1) As such, the defendant is not entitled to an automatic reversal and the prosecution may attempt to argue that the jury would have returned the same result if the error had not occurred.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"law","label":"Bipartisan Safer Communities Act, Pub. L. No. 117-159","url":"https://www.govinfo.gov/link/plaw/117/public/159","by":{"1":"3"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","subs":["(b)(2)"],"stext":{"head":"§1326. Reentry of removed aliens","paras":[[0,"(a) In general"],[0,"Subject to subsection (b), any alien who—"],[1,"(1) has been denied admission, excluded, deported, or removed or has departed the United States while an order of exclusion, deportation, or removal is outstanding, and thereafter"],[1,"(2) enters, attempts to enter, or is at any time found in, the United States, unless (A) prior to his reembarkation at a place outside the United States or his application for admission from foreign contiguous territory, the Attorney General has expressly consented to such alien's reapplying for admission; or (B) with respect to an alien previously denied admission and removed, unless such alien shall establish that he was not required to obtain such advance consent under this chapter or any prior Act,"],[0,"shall be fined under title 18, or imprisoned not more than 2 years, or both."],[0,"(b) Criminal penalties for reentry of certain removed aliens"],[0,"Notwithstanding subsection (a), in the case of any alien described in such subsection—"],[1,"(1) whose removal was subsequent to a conviction for commission of three or more misdemeanors involving drugs, crimes against the person, or both, or a felony (other than an aggravated felony), such alien shall be fined under title 18, imprisoned not more than 10 years, or both;"],[1,"(2) whose removal was subsequent to a conviction for commission of an aggravated felony, such alien shall be fined under such title, imprisoned not more than 20 years, or both;"],[1,"(3) who has been excluded from the United States pursuant to section 1225(c) of this title because the alien was excludable under section 1182(a)(3)(B) of this title or who has been removed from the United States pursuant to the provisions of subchapter V, and who thereafter, without the permission of the Attorney General, enters the United States, or attempts to do so, shall be fined under title 18 and imprisoned for a period of 10 years, which sentence shall not run concurrently with any other sentence.1 or"],[1,"(4) who was removed from the United States pursuant to section 1231(a)(4)(B) of this title who thereafter, without the permission of the Attorney General, enters, attempts to enter, or is at any time found in, the United States (unless the Attorney General has expressly consented to such alien's reentry) shall be fined under title 18, imprisoned for not more than 10 years, or both."],[0,"For the purposes of this subsection, the term \"removal\" includes any agreement in which an alien stipulates to removal during (or not during) a criminal trial under either Federal or State law."],[0,"(c) Reentry of alien deported prior to completion of term of imprisonment"],[0,"Any alien deported pursuant to section 1252(h)(2) 2 of this title who enters, attempts to enter, or is at any time found in, the United States (unless the Attorney General has expressly consented to such alien's reentry) shall be incarcerated for the remainder of the sentence of imprisonment which was pending at the time of deportation without any reduction for parole or supervised release. Such alien shall be subject to such other penalties relating to the reentry of deported aliens as may be available under this section or any other provision of law."],[0,"(d) Limitation on collateral attack on underlying deportation order"],[0,"In a criminal proceeding under this section, an alien may not challenge the validity of the deportation order described in subsection (a)(1) or subsection (b) unless the alien demonstrates that—"],[1,"(1) the alien exhausted any administrative remedies that may have been available to seek relief against the order;"],[1,"(2) the deportation proceedings at which the order was issued improperly deprived the alien of the opportunity for judicial review; and"],[1,"(3) the entry of the order was fundamentally unfair."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1326?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1326. Reentry of removed aliens","tname":"Aliens and Nationality","by":{"1":"15","2":"3"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"1":"3, 16, 26, 27, 2, 3"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"1":"2, 4"}},{"t":"case","label":"Ashe v. Swenson","cite":"397 U.S. 436","y":1970,"id":"1969/57","sc":1,"sum":"Three or four men robbed six poker players. Petitioner was separately charged with having robbed one of the players, Knight, who along with three others testified for the prosecution that each had been robbed. The State's evidence that petitioner had been one of the robbers was weak. The defense offered no testimony. The trial judge instructed the jury that if it found that petitioner participated in the robbery, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"Connick v. Thompson","cite":"563 U.S. 51","y":2011,"id":"2010/09-571","sc":1,"sum":"The Court held that a prosecutor's office cannot be held liable for the illegal conduct of one of its employees when there has only been one violation resulting from allegedly deficient training.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"597 U.S. 215","y":2022,"id":"2021/19-1392","sc":1,"sum":"The Constitution does not confer a right to abortion; Roe v. Wade, 410 U. S. 113, and Planned Parenthood of Southeastern Pa. v. Casey, 505 U. S. 833, are overruled; the authority to regulate abortion is returned to the people and their elected representatives.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5"}},{"t":"case","label":"Duncan v. Louisiana","cite":"391 U.S. 145","y":1968,"id":"1967/410","sc":1,"op":1,"sum":"The Court ruled that the right to a jury trial in state prosecutions where sentences may be as long as two years were protected under the Sixth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Leland v. Oregon","cite":"343 U.S. 790","y":1952,"id":"scdb/1951-094","sc":1,"sum":"These statutes did not deprive appellant of life and liberty without due process of law in violation of the Fourteenth Amendment of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"McNeill v. United States","cite":"563 U.S. 816","y":2011,"id":"2010/10-5258","sc":1,"op":1,"ar":1,"sum":"The Court held that a federal sentencing court must determine whether an offense under state law is a \"serious drug offense\" within the meaning of the Armed Career Criminal Act by consulting the maximum sentence applicable at the time of the defendant's conviction.","sumSrc":"Oyez","by":{"2":"10, 11"}},{"t":"case","label":"Patterson v. New York","cite":"432 U.S. 197","y":1977,"id":"1976/75-1861","sc":1,"sum":"New York law requiring that the defendant in a prosecution for seconddegree murder prove by a preponderance of the evidence the affirmative defense of extreme emotional disturbance in order to reduce the crime to manslaughter held not to violate the Due Process Clause of the Fourteenth Amendment. Mullaney v. Wilbur, 421 U. S. 684, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"op":4,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Rose v. Clark","cite":"478 U.S. 570","y":1986,"id":"1985/84-1974","sc":1,"op":1,"sum":"Respondent was charged with the murder of two persons arising from the same incident. At his trial in a Tennessee state court he defended on the ground, inter alia, that he was either insane or incapable of forming the requisite intent to kill the victims. The court instructed the jury on both first-degree murder, which requires proof of premeditation and deliberation under Tennessee law, and second-degree murder, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Seminole Tribe v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Spencer v. Texas","cite":"385 U.S. 554","y":1967,"id":"1966/68","sc":1,"op":7,"ar":2,"sum":"Observing that, whether or not required to do so, at the time most States had adopted “procedures which postpone the introduction of prior convictions until after the jury has found the defendant guilty of the crime currently charged”.","sumSrc":"opinion","by":{"2":"16, 17, 18"}},{"t":"case","label":"State v. Briggs","cite":"145 P. 866","y":1915,"court":"Kan.","url":"https://www.courtlistener.com/c/P./145/866/","by":{"2":"6"}},{"t":"case","label":"(continued) Page(s) Taylor v. Louisiana","cite":"419 U.S. 522","y":1975,"id":"1974/73-5744","sc":1,"op":55,"sum":"The Court held that a jury made up of a representative cross-section of the community is an essential component of the Sixth Amendment.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"United States v. Del Valle-Fuentes","cite":"143 F. Supp. 3d 24","y":2015,"court":"D.P.R.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/143/24/","by":{"2":"19"}},{"t":"case","label":"United States v. Guerrero-Jasso","cite":"752 F.3d 1186","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/752/1186/","by":{"2":"3"}},{"t":"case","label":"United States v. Rojas-Luna","cite":"522 F.3d 502","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/522/502/","by":{"2":"3"}},{"t":"case","label":"United States v. Steffes","cite":"2016 WL 1175205","y":2016,"court":"N.D. Iowa Mar. 23","by":{"2":"19"}},{"t":"case","label":"United States v. Tsarnaev","cite":"595 U.S. 302","y":2022,"id":"2021/20-443","sc":1,"op":4,"sum":"The judgment of the Court of Appeals vacating Tsarnaev’s capital sentences is reversed.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"United States v. Young","cite":"503 F.2d 1072","y":1974,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/503/1072/","by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 3591","url":"https://www.law.cornell.edu/uscode/text/18/3591","by":{"2":"18"}},{"t":"usc","label":"18 U.S.C. § 3593","url":"https://www.law.cornell.edu/uscode/text/18/3593","by":{"2":"18"}}]};